def _is_loopback_port_authority(authority):
    try:
        parsed = urlsplit("//{}".format(authority))
        port = parsed.port
    except ValueError:
        return False
    return (
        parsed.hostname == "127.0.0.1"
        and port is not None
        and 1 <= port <= 65535
        and parsed.username is None
        and parsed.password is None
        and parsed.path == ""
        and parsed.netloc == "127.0.0.1:{}".format(port)
    )


