class LoopbackHTTPServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def main():
    parser = argparse.ArgumentParser(
        description="AssureBench local-first DevSecOps security assessment."
    )
    commands = parser.add_subparsers(dest="command")
    scan_parser = commands.add_parser(
        "scan",
        help="scan a local repository directory and emit a Markdown report",
    )
    scan_parser.add_argument(
        "project",
        type=Path,
        help="path to the local repository directory to assess",
    )
    scan_parser.add_argument(
        "--output",
        "-o",
        type=Path,
        help="write the Markdown report to this file instead of stdout",
    )
    scan_parser.add_argument(
        "--verbose",
        action="store_true",
        help="also show scanner log output on stderr",
    )
    args = parser.parse_args()
    if args.command == "scan":
        return run_cli_scan(args.project, args.output, args.verbose)
    return run_dashboard()


def run_dashboard():
    if os.environ.get("SECURITY_SCAN_HOST") or os.environ.get("SECURITY_SCAN_PORT"):
        raise SystemExit("Host and port overrides are intentionally disabled; this service must stay loopback-only.")
    bind_host = "0.0.0.0" if CONTAINER_MODE else "127.0.0.1"
    server = LoopbackHTTPServer((bind_host, PORT), RequestHandler)
